//! Golden test of `TreeFeature` and `FallenTreeFeature` (all trunk/foliage/root placers, decorators and feature sizes through
//! the data pack's entries) against the real vanilla classes: every `tree` / `fallen_tree` entry is placed 6 times in a region
//! of the synthetic terrain for 5 terrain variants (plain, snow, soils, obstacles, flooded) and different seeds/chunks.
//! Fixture `tests/fixtures/tree_golden.txt` is generated by `tests/oracle/TreeOracle.java`; per scenario the test compares the
//! result and the next RNG value of every placement and the digests of the dump of the region (blocks, block entity NBT,
//! heightmaps, post-processing, ticks, entities, region random).
//!
//! On a mismatch the Rust dump is written to `/tmp/tree_golden_<scenario>.rust.txt`; regenerate the vanilla one with
//! `scripts/vanilla-java.sh crates/mc-game/tests/oracle/TreeOracle.java /tmp/v.txt <scenario> full` and diff the `L` lines.

mod common;

use common::feature_harness::*;
use mc_core::ident::Identifier;
use mc_core::pos::BlockPos;
use mc_core::random::{RandomSource, XoroshiroRandomSource};
use mc_game::world::level::levelgen::gen_level::GenLevel;
use mc_game::world::level::levelgen::registries::GenRegistries;
use mc_game::world::level::{BlockGetter, LevelAccessor, LevelReader};
use mc_world::heightmap::HeightmapType;
use mc_world::status::ChunkStatus;
use mc_worldgen::data::{FsDataSource, WorldgenDataSource};
use std::collections::BTreeMap;
use std::sync::{Arc, LazyLock};

const VARIANTS: i32 = 5;

/// The registries the scenarios place from: the complete vanilla ones when they decode, otherwise only the tree entries
/// (and the block state providers) of the data pack.
static REGISTRIES: LazyLock<Arc<GenRegistries>> = LazyLock::new(|| {
    if WORLD.registries_loaded {
        return WORLD.registries.clone();
    }
    struct TreesOnly(FsDataSource);
    impl WorldgenDataSource for TreesOnly {
        fn get(&self, registry: &str, id: &Identifier) -> Option<serde_json::Value> {
            self.0.get(registry, id)
        }

        fn list(&self, registry: &str) -> Vec<Identifier> {
            let ids = self.0.list(registry);
            let is_tree = |id: &Identifier| {
                let ty = self.0.get("worldgen/feature", id).and_then(|v| v["type"].as_str().map(str::to_owned));
                matches!(ty.as_deref(), Some("minecraft:tree" | "minecraft:fallen_tree"))
            };
            match registry {
                "worldgen/feature" => ids.into_iter().filter(|id| is_tree(id)).collect(),
                // a placed feature references its configured feature by id (inline definitions are never a tree here)
                "worldgen/placed_feature" => ids
                    .into_iter()
                    .filter(|id| {
                        let feature = self.0.get(registry, id).and_then(|v| v["feature"].as_str().map(str::to_owned));
                        feature.and_then(|f| Identifier::parse(&f).ok()).is_some_and(|f| is_tree(&f))
                    })
                    .collect(),
                _ => ids,
            }
        }
    }
    let root = std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("../../ref/src/data");
    Arc::new(GenRegistries::load(Arc::new(TreesOnly(FsDataSource::new(root))), &WORLD.worldgen, &WORLD.biomes).expect("tree registries decode"))
});

fn put(level: &mut GenLevel<'_>, x: i32, y: i32, z: i32, state: &str) {
    level.set_block(BlockPos::new(x, y, z), parse_state(state), 18, 512);
}

fn is_air(level: &GenLevel<'_>, x: i32, y: i32, z: i32) -> bool {
    level.get_block_state(BlockPos::new(x, y, z)).is_air()
}

/// `TreeOracle.prepare`: the terrain variants (mirror of the Java method).
fn prepare(level: &mut GenLevel<'_>, seed: i64, variant: i32, cx: i32, cz: i32) {
    for x in cx * 16 - 8..cx * 16 + 24 {
        for z in cz * 16 - 8..cz * 16 + 24 {
            let top = surface_top(seed, x, z);
            let hv = h(seed, i64::from(x), i64::from(z), i64::from(100 + variant));
            let hv8 = ((hv as u64) >> 8) as i64;
            let ground = state_string(level.get_block_state(BlockPos::new(x, top - 1, z)));
            let grass = ground.starts_with("minecraft:grass_block");
            let dirty = grass || ground.starts_with("minecraft:dirt");
            match variant {
                1 => {
                    if grass {
                        put(level, x, top - 1, z, "minecraft:grass_block[snowy=true]");
                    }
                    if top >= 63 && is_air(level, x, top, z) && hmod(hv, 4) != 0 {
                        put(level, x, top, z, &format!("minecraft:snow[layers={}]", 1 + hmod(hv8, 3)));
                    }
                }
                2 => {
                    if dirty {
                        match hmod(hv, 5) {
                            0 => put(level, x, top - 1, z, "minecraft:podzol[snowy=false]"),
                            1 => put(level, x, top - 1, z, "minecraft:coarse_dirt"),
                            2 => put(level, x, top - 1, z, "minecraft:mud"),
                            3 => put(level, x, top - 1, z, "minecraft:rooted_dirt"),
                            _ => {}
                        }
                    }
                }
                3 => {
                    let r = hmod(hv, 40);
                    let d = hmod(h(seed, i64::from(x), i64::from(z), 200), 3);
                    if r < 3 {
                        if is_air(level, x, top + 1 + d, z) {
                            put(level, x, top + 1 + d, z, "minecraft:oak_leaves[distance=7,persistent=true,waterlogged=false]");
                        }
                    } else if r < 5 {
                        if is_air(level, x, top, z) {
                            put(level, x, top, z, "minecraft:vine[south=true]");
                        }
                    } else if r < 7 {
                        for y in top..top + 3 {
                            if is_air(level, x, y, z) {
                                put(level, x, y, z, "minecraft:oak_log[axis=y]");
                            }
                        }
                    } else if r < 9 {
                        for y in top..top + 2 + d {
                            if is_air(level, x, y, z) {
                                put(level, x, y, z, "minecraft:stone");
                            }
                        }
                    } else if r < 20 {
                        if is_air(level, x, top, z) {
                            put(level, x, top, z, "minecraft:short_grass");
                        }
                    } else if r < 24 && is_air(level, x, top + 1, z) {
                        put(level, x, top + 1, z, "minecraft:oak_leaves[distance=4,persistent=false,waterlogged=false]");
                    }
                }
                4 => {
                    if top <= 65 {
                        if dirty && hmod(hv, 2) == 0 {
                            put(level, x, top - 1, z, "minecraft:mud");
                        }
                        for y in top..=65 {
                            if is_air(level, x, y, z) {
                                put(level, x, y, z, "minecraft:water[level=0]");
                            }
                        }
                    }
                }
                _ => {}
            }
        }
    }
}

#[test]
fn trees_match_vanilla() {
    let fixture = std::fs::read_to_string(concat!(env!("CARGO_MANIFEST_DIR"), "/tests/fixtures/tree_golden.txt")).expect("fixture present");
    let mut lines = fixture.lines();
    let mut failures: Vec<String> = Vec::new();
    let (mut scenarios, mut placements, mut placed_trees, mut dump_lines) = (0, 0, 0, 0);
    while let Some(header) = lines.next() {
        let head: Vec<&str> = header.split(' ').collect();
        assert_eq!(head[0], "SCENARIO", "{header}");
        let (scenario, feature_id, seed) = (head[1], head[2], head[3].parse::<i64>().unwrap());
        let (variant, cx, cz) = (head[4].parse::<i32>().unwrap(), head[5].parse::<i32>().unwrap(), head[6].parse::<i32>().unwrap());
        let feature = REGISTRIES.feature(&Identifier::parse(feature_id).unwrap()).unwrap_or_else(|| panic!("feature {feature_id}")).clone();
        let fi = scenario.parse::<i64>().unwrap() / i64::from(VARIANTS);

        let mut synth = SynthRegion::new(seed, cx, cz, ChunkStatus::Features, 1);
        let mut env = Arc::try_unwrap(gen_env(seed)).ok().expect("fresh env");
        env.registries = REGISTRIES.clone();
        synth.env = Arc::new(env);
        let env = synth.env.clone();
        prepare(&mut synth.level(), seed, variant, cx, cz);
        let before = snapshot(&synth);
        let mut level = synth.level();
        let mut expected: Vec<String> = Vec::new();
        let mut got: Vec<String> = Vec::new();
        for line in lines.by_ref() {
            if line == "END" {
                break;
            }
            expected.push(line.to_string());
        }
        for i in 0..6i64 {
            let x = cx * 16 + hmod(h(seed, fi, i, 11), 16);
            let z = cz * 16 + hmod(h(seed, fi, i, 12), 16);
            let mut y = level.get_height_at(HeightmapType::OceanFloor, x, z);
            match hmod(h(seed, fi, i, 13), 6) {
                0 => y -= 1,
                1 => y += 1,
                2 => y += 2,
                _ => {}
            }
            let mut random = XoroshiroRandomSource::new(h(seed, fi, i, 14));
            let placed = feature.value().place(&mut level, &env, &mut random, BlockPos::new(x, y, z));
            placements += 1;
            placed_trees += usize::from(placed);
            got.push(format!("P {i} {x} {y} {z} {placed} {}", random.next_long()));
        }
        let dump_all = dump(&mut level, &before);
        dump_lines += dump_all.len();
        let mut digests: BTreeMap<String, Fnv> = BTreeMap::new();
        for line in &dump_all {
            digests.entry(line[..1].to_string()).or_default().s(line);
        }
        for (kind, f) in &digests {
            got.push(format!("D {kind} {} {}", f.count, f.hex()));
        }
        if got != expected {
            let _ = std::fs::write(format!("/tmp/tree_golden_{scenario}.rust.txt"), dump_all.join("\n"));
            let first = got.iter().zip(&expected).position(|(a, b)| a != b).unwrap_or(got.len().min(expected.len()));
            failures.push(format!(
                "scenario {scenario} ({feature_id} variant {variant}): first difference at line {first}: ours `{}`, vanilla `{}`",
                got.get(first).map_or("<none>", String::as_str),
                expected.get(first).map_or("<none>", String::as_str)
            ));
        }
        scenarios += 1;
    }
    assert!(failures.is_empty(), "{} of {scenarios} scenarios differ ({placements} placements):\n{}", failures.len(), failures.join("\n"));
    assert!(scenarios >= 250 && placed_trees > 500 && dump_lines > 10_000, "fixture too small/degenerate: {scenarios} scenarios, {placed_trees} placed, {dump_lines} dump lines");
}
